<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/config/database.php';require_once __DIR__.'/lib/resume_storage.php';
$id=trim($_GET['id']??'');$download=($_GET['download']??'')==='1';$stmt=db()->prepare('SELECT id,stored_file,source_url,name FROM candidates WHERE id=?');$stmt->execute([$id]);$candidate=$stmt->fetch();if(!$candidate||!$candidate['stored_file']){http_response_code(404);exit('Resume not found.');}
$path=resolveCandidateResumePath($candidate,currentUser()['id']??null);if(!$path){http_response_code(404);exit('Resume file is unavailable locally and could not be retrieved from its approved source.');}
$mime=(new finfo(FILEINFO_MIME_TYPE))->file($path)?:'application/octet-stream';$allowed=['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/msword'];if(!in_array($mime,$allowed,true)){http_response_code(415);exit('Unsupported resume type.');}
db()->prepare('INSERT INTO audit_events(user_id,action,entity_type,entity_id,metadata_json) VALUES(?,?,?,?,?)')->execute([currentUser()['id'],$download?'resume_download':'resume_view','candidate',$id,json_encode(['mime'=>$mime])]);$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$safe=preg_replace('/[^A-Za-z0-9._-]+/','_',trim($candidate['name'])).'-resume.'.$ext;header('Content-Type: '.$mime);header('Content-Length: '.filesize($path));header('Content-Disposition: '.($download?'attachment':'inline').'; filename="'.$safe.'"');header('X-Content-Type-Options: nosniff');readfile($path);
